import './style.css';
import {registry,defaultWallpaperId} from './wallpapers/registry';
import {WallpaperRuntime,type RuntimeSnapshot,type Enhancement} from './render/wallpaper-runtime';
import type {Triple} from './content/package-contract';
import {createWallpaperClock} from './ui/wallpaper-clock';
const el=<T extends HTMLElement=HTMLElement>(id:string)=>document.getElementById(id)! as T;
const query=new URLSearchParams(location.search),host=el('stage'),status=el('status');
const selected=registry.get(query.get('wallpaper')??defaultWallpaperId);
let runtime:WallpaperRuntime,localTimer:ReturnType<typeof setInterval>|null=null,lastReport=0;
interface Preferences{local:boolean;automatic:boolean;minutes:number;motion:boolean;particles:boolean;lamps:boolean;rim:boolean;wind:boolean;bloom:boolean;grade:boolean;showClock:boolean;speed:number;exposure:number;light:number;shadow:number;fit:'cover'|'contain';quality:number}
const settings:Preferences={local:true,automatic:false,minutes:720,motion:true,particles:true,lamps:true,rim:true,wind:true,bloom:true,grade:true,showClock:true,speed:1,exposure:0,light:1,shadow:1,fit:'cover',quality:1};
const preferenceKey='wallpaper-settings-v1:'+(selected?.wallpaper.id??defaultWallpaperId);
try{const saved=JSON.parse(localStorage.getItem(preferenceKey)??'null');if(saved){for(const k of ['local','automatic','motion','particles','lamps','rim','wind','bloom','grade','showClock'] as const)if(typeof saved[k]==='boolean')settings[k]=saved[k];for(const [key,min,max] of [['minutes',0,1439],['speed',.5,1.5],['exposure',-.8,.8],['light',.5,1.5],['shadow',0,1.3]] as const)if(typeof saved[key]==='number'&&Number.isFinite(saved[key])&&saved[key]>=min&&saved[key]<=max)settings[key]=saved[key];if(['cover','contain'].includes(saved.fit))settings.fit=saved.fit;if([1,1.5,2].includes(saved.quality))settings.quality=saved.quality}}catch{}
function save(){try{localStorage.setItem(preferenceKey,JSON.stringify(settings))}catch{}}
const clock=createWallpaperClock(el('wallpaper-clock'),el<HTMLTimeElement>('clock-time'),el('clock-date'),el('clock-year'));
clock.setVisible(settings.showClock);el<HTMLInputElement>('show-clock').checked=settings.showClock;
el<HTMLInputElement>('show-clock').onchange=event=>{settings.showClock=(event.target as HTMLInputElement).checked;clock.setVisible(settings.showClock);save()};
window.addEventListener('pagehide',event=>{if(!event.persisted)clock.destroy()});
function openPanel(open:boolean){el('control-panel').hidden=!open;el('panel-toggle').setAttribute('aria-expanded',String(open));if(open)el<HTMLButtonElement>('close-panel').focus();else el('panel-toggle').focus()}
el('panel-toggle').onclick=()=>openPanel(el('control-panel').hidden===true);
el('close-panel').onclick=()=>openPanel(false);
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!el('control-panel').hidden)openPanel(false)});
host.onclick=()=>{if(!el('control-panel').hidden)openPanel(false)};
const tabs=[...document.querySelectorAll<HTMLButtonElement>('[data-tab]')];
function selectTab(tab:HTMLButtonElement){for(const item of tabs){const active=item===tab;item.setAttribute('aria-selected',String(active));item.tabIndex=active?0:-1;el('section-'+item.dataset.tab).hidden=!active}}
for(const tab of tabs){tab.onclick=()=>selectTab(tab);tab.onkeydown=event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const i=event.key==='Home'?0:event.key==='End'?tabs.length-1:(tabs.indexOf(tab)+(event.key==='ArrowRight'?1:tabs.length-1))%tabs.length;selectTab(tabs[i]);tabs[i].focus()}}
selectTab(tabs[0]);
function timeText(minutes:number){return String(Math.floor(minutes/60)%24).padStart(2,'0')+':'+String(Math.floor(minutes%60)).padStart(2,'0')}
function report(now:number,snapshot:RuntimeSnapshot){if(settings.motion&&now-lastReport<500)return;lastReport=now;el('runtime-report').textContent=JSON.stringify(snapshot);el<HTMLInputElement>('time').value=String(Math.round(snapshot.lightingMinutes));const text=timeText(snapshot.lightingMinutes);el('time-label').textContent=text;el('pill-time').textContent=text;for(const preset of document.querySelectorAll<HTMLButtonElement>('[data-minutes]'))preset.setAttribute('aria-pressed',String(!settings.local&&!settings.automatic&&Math.abs(Number(preset.dataset.minutes)-snapshot.lightingMinutes)<1));if(snapshot.loadError){status.hidden=false;status.textContent='资源加载失败：'+snapshot.loadError}else status.hidden=true}
function stopLocal(){if(localTimer!==null)clearInterval(localTimer);localTimer=null}
function applyTime(){stopLocal();runtime.lightingAutomatic=settings.automatic&&!settings.local;el<HTMLInputElement>('local').checked=settings.local;el<HTMLInputElement>('automatic').checked=settings.automatic&&!settings.local;if(settings.local){const follow=()=>{const date=new Date();runtime.setTime(date.getHours()*60+date.getMinutes()+date.getSeconds()/60)};follow();localTimer=setInterval(follow,1000)}else runtime.setTime(settings.minutes)}
function applyLight(){runtime.setExposureEV(settings.exposure);runtime.setLightStrength(settings.light);runtime.setShadowStrength(settings.shadow);el<HTMLInputElement>('exposure').value=String(settings.exposure);el<HTMLInputElement>('light-strength').value=String(settings.light);el<HTMLInputElement>('shadow-strength').value=String(settings.shadow);el('exposure-label').textContent=(settings.exposure>0?'+':'')+settings.exposure.toFixed(2)+' EV';el('light-strength-label').textContent=Math.round(settings.light*100)+'%';el('shadow-strength-label').textContent=Math.round(settings.shadow*100)+'%'}
function navigateWallpaper(id:string){if(id===selected?.wallpaper.id)return;const url=new URL(location.href);url.searchParams.set('wallpaper',id);url.searchParams.delete('revision');location.assign(url)}
try{
 if(!selected)throw Error('未注册的壁纸组合');
 runtime=await WallpaperRuntime.create(host,selected.character,selected.scene,selected.wallpaper,{frameTransport:query.get('frames')==='full'?'full':'auto'});runtime.onFrame=report;
 document.title=(runtime.character.displayName??runtime.character.id)+' · '+(runtime.wallpaper.presentation?.sceneName??runtime.wallpaper.displayName??'风与昼夜');
 const focus=runtime.wallpaper.presentation?.focus??[.5,.5];host.style.setProperty('--focus',focus.map(v=>v*100+'%').join(' '));host.dataset.fit=settings.fit;el<HTMLSelectElement>('fit').value=settings.fit;
 el('current-wallpaper').textContent=(runtime.character.displayName??runtime.character.id)+' · '+(runtime.wallpaper.presentation?.sceneName??runtime.wallpaper.displayName??'');
 for(const preset of runtime.scenePackage.controls.presets){const button=document.createElement('button');button.textContent=preset.name;button.dataset.minutes=String(preset.minutes);button.setAttribute('aria-pressed','false');button.onclick=()=>{settings.local=false;settings.automatic=false;settings.minutes=preset.minutes;applyTime();save()};el('day-presets').append(button)}
 el<HTMLInputElement>('time').oninput=event=>{settings.local=false;settings.automatic=false;settings.minutes=Number((event.target as HTMLInputElement).value);applyTime();save()};
 el<HTMLInputElement>('local').onchange=event=>{settings.local=(event.target as HTMLInputElement).checked;settings.automatic=false;settings.minutes=Math.min(1439,runtime.snapshot().lightingMinutes);applyTime();save()};
 el<HTMLInputElement>('automatic').onchange=event=>{settings.automatic=(event.target as HTMLInputElement).checked;settings.local=false;settings.minutes=Math.min(1439,runtime.snapshot().lightingMinutes);applyTime();save()};
 for(const [id,key] of [['exposure','exposure'],['light-strength','light'],['shadow-strength','shadow']] as const)el<HTMLInputElement>(id).oninput=event=>{settings[key]=Number((event.target as HTMLInputElement).value);applyLight();save()};
 el('reset-light').onclick=()=>{settings.exposure=0;settings.light=1;settings.shadow=1;for(const key of ['lamps','rim','bloom','grade'] as Enhancement[]){settings[key]=true;el<HTMLInputElement>('effect-'+key).checked=true;runtime.setEnhancement(key,true)}applyLight();save()};
 for(const key of ['lamps','rim','wind','bloom','grade'] as Enhancement[]){const input=el<HTMLInputElement>('effect-'+key);input.checked=settings[key];runtime.setEnhancement(key,settings[key]);input.onchange=()=>{settings[key]=input.checked;runtime.setEnhancement(key,input.checked);save()}}el<HTMLInputElement>('particles').checked=settings.particles;runtime.setParticles(settings.particles);el<HTMLInputElement>('particles').onchange=event=>{settings.particles=(event.target as HTMLInputElement).checked;runtime.setParticles(settings.particles);save()};el<HTMLInputElement>('motion').checked=settings.motion;runtime.setPaused(!settings.motion);el<HTMLInputElement>('motion').onchange=event=>{settings.motion=(event.target as HTMLInputElement).checked;runtime.setPaused(!settings.motion);save()};
 el<HTMLInputElement>('speed').value=String(settings.speed);el('speed-label').textContent=settings.speed.toFixed(1)+'×';runtime.setPlaybackRate(settings.speed);el<HTMLInputElement>('speed').oninput=event=>{settings.speed=Number((event.target as HTMLInputElement).value);runtime.setPlaybackRate(settings.speed);el('speed-label').textContent=settings.speed.toFixed(1)+'×';save()};
 el<HTMLSelectElement>('fit').onchange=event=>{settings.fit=(event.target as HTMLSelectElement).value as Preferences['fit'];host.dataset.fit=settings.fit;save()};
 el<HTMLSelectElement>('quality').value=String(settings.quality);runtime.setQuality(settings.quality);el<HTMLSelectElement>('quality').onchange=event=>{settings.quality=Number((event.target as HTMLSelectElement).value);runtime.setQuality(settings.quality);save()};
 el('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{status.textContent='当前窗口暂不支持全屏，可使用窗口最大化观看。';status.hidden=false}};
 document.addEventListener('fullscreenchange',()=>{el('fullscreen').textContent=document.fullscreenElement?'退出全屏':'进入全屏'});
 const published=[...registry.values()].filter(item=>item.wallpaper.presentation?.selectable),characters=new Map<string,(typeof published)[number]>();
 for(const item of published){const key=item.wallpaper.presentation!.characterKey;if(!characters.has(key)||item.wallpaper.id===selected.wallpaper.id)characters.set(key,item)}
 for(const [key,item] of characters){const button=document.createElement('button');button.className='character-card';button.setAttribute('aria-label','选择角色 '+(item.character.displayName??key));button.setAttribute('aria-pressed',String(key===selected.wallpaper.presentation?.characterKey));const thumbnail=item.wallpaper.presentation?.thumbnail;if(thumbnail){const image=document.createElement('img');image.src=import.meta.env.BASE_URL+thumbnail;image.alt='';button.append(image)}const label=document.createElement('span');label.textContent=item.character.displayName??key;button.append(label);button.onclick=()=>navigateWallpaper(item.wallpaper.id);el('character-list').append(button)}
 for(const item of published.filter(item=>item.wallpaper.presentation?.characterKey===selected.wallpaper.presentation?.characterKey)){const option=document.createElement('option');option.value=item.wallpaper.id;option.textContent=item.wallpaper.presentation!.sceneName;option.selected=item.wallpaper.id===selected.wallpaper.id;el<HTMLSelectElement>('scene-choice').append(option)}
 el<HTMLSelectElement>('scene-choice').onchange=event=>navigateWallpaper((event.target as HTMLSelectElement).value);
 if(query.get('debug')==='1'){el('debug-controls').hidden=false;el<HTMLSelectElement>('background').onchange=event=>runtime.setBackground((event.target as HTMLSelectElement).value);const directions:Record<string,Triple|null>={daylight:null,front:[0,0,1],left:[-.82,-.12,.56],right:[.82,-.12,.56],low:[0,.8,.6]};el<HTMLSelectElement>('direction').onchange=event=>runtime.setTestDirection(directions[(event.target as HTMLSelectElement).value]);el<HTMLSelectElement>('diagnostic').onchange=event=>runtime.setDiagnostic(Number((event.target as HTMLSelectElement).value))}
 applyTime();applyLight();lastReport=-Infinity;report(performance.now(),runtime.snapshot());
 const lifecycle:unknown[]=[];document.addEventListener('visibilitychange',()=>{lifecycle.push({at:new Date().toISOString(),hidden:document.hidden,...runtime.snapshot()});if(lifecycle.length>32)lifecycle.shift();el('lifecycle-report').textContent=JSON.stringify(lifecycle)});
 window.addEventListener('pagehide',event=>{if(!event.persisted){stopLocal();runtime.destroy()}});
}catch(error){status.hidden=false;status.textContent='加载失败：'+String(error)}
